-- S17: independent Claude attestation; exact package hash; only AUTO; no legacy mutation.
BEGIN;
DO $s17$
DECLARE p jsonb; e record; h text; val jsonb; ans jsonb; cd text; n int:=0; pub int:=0; links int:=0; b_leg jsonb; b_dep jsonb; lid int; residual text; diff text; old_desc text; new_desc text;
BEGIN
 SELECT jsonb_agg(to_jsonb(t) ORDER BY id) INTO b_leg FROM lf_ops.reglas t;
 SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones t;
 FOR p IN SELECT value FROM jsonb_array_elements($pack$[{"codigo":"S17-C01","version":1,"eval_id":1128,"hash_version_atestado":"a5dc950b252c664af9a41949019376144f108628b40456722fc04750bf80b714","hash_paquete_atestado":"b8a58c8e5ca1fedc456ecd1f4472b16de16cc04b59faba05a641f584dc1db95c","veredicto":"PASS","juez":"Claude independiente 2026-11-24 13:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":657,"familia":"SECURITY","diferencias":"Contraste funcional: BLOQUEAR certificación del Login B2B sin evidencia de controles contra agotamiento de recursos y DDoS, inyección mediante validación server-side y consultas parametrizadas, XSS, SSRF, clickjacking, CORS, TLS y headers, replay, supply chain/SBOM y límites de payload. No afirmar implementación ni QA aprobada sin evidencia. La legada declara implementación y QA pendientes; no afirmarlas sin evidencia.","residual":"","complementa":null},{"codigo":"S17-C02","version":1,"eval_id":1129,"hash_version_atestado":"874f6f3536583228d822f76c87ff8095a8ec2b7415e0da8f3efbcaece1383a45","hash_paquete_atestado":"3daffbb168e0ba8bf307b4ac05d9cbd1ecd6c1a8260e01e0ff2e4760715c155c","veredicto":"PASS","juez":"Claude independiente 2026-11-24 13:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":559,"familia":"OFFERS_INSTALLMENTS","diferencias":"Contraste funcional: BLOQUEAR modal de cuotas que preseleccione plan nuevo, habilite Aplicar sin plan válido, persista cambios antes de Aplicar o altere selección comprometida al cancelar o cerrar. Solo restaurar plan previo de misma oferta, versión y vigencia; aplicar revalidación backend y actualizar únicamente oferta contextual y resumen, sin cálculo monetario frontend.","residual":"","complementa":null},{"codigo":"S17-C03","version":1,"eval_id":1130,"hash_version_atestado":"216ed16e3c7860c596cc3379f87fe3d96340a629649f56cad2fd69d92edd24b3","hash_paquete_atestado":"00701fd25d8b697cc313f2029e83ec09b03ef66c0c26111f300181c131e70207","veredicto":"PASS","juez":"Claude independiente 2026-11-24 13:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":369,"familia":"DESIGN_SYSTEM","diferencias":"Contraste funcional: BLOQUEAR bloque de confianza de Home que desplace jerarquía del Hero, Ruta de Claridad o CTA principal, incluya CTA del simulador o agregue panel explicativo sin evidencia real.","residual":"","complementa":null},{"codigo":"S17-C04","version":1,"eval_id":1131,"hash_version_atestado":"99c4e23c635eb20be67c79fff87f715200cc5b0cf3ca9f52d82bb5e29e002a05","hash_paquete_atestado":"d60a66a09d3c2ce623363a3acb16063bb9bb19413003a0b1d08909bcb36ae4a8","veredicto":"PASS","juez":"Claude independiente 2026-11-24 13:35 Lima","modo":"INDEPENDIENTE","revisor_es_productor":false,"llamadas_modelo":1,"puntajes":{"CAL_CLARIDAD":{"puntaje":1},"CAL_ACCIONABLE":{"puntaje":1},"CAL_ALCANCE":{"puntaje":1},"SEM_NO_DUPLICA":{"puntaje":1},"SEM_NO_CONTRADICE":{"puntaje":1},"COH_TEXTO_CONDICION":{"puntaje":1},"COH_EFECTO":{"puntaje":1}},"legada_id":361,"familia":"DESIGN_SYSTEM","diferencias":"Contraste funcional: BLOQUEAR restricción de slate_text_strong exclusivamente al Hero cuando un subtítulo, disclaimer o microcopy de Home requiera margen de contraste; usar token canónico sin copiar hex ni fijar nuevas métricas. Conserva alcance amplio de slate_text_strong a Home.","residual":"","complementa":null}]$pack$::jsonb) LOOP
 cd:=p->>'codigo'; lid:=(p->>'legada_id')::int;
 SELECT id,regla,version,hash_paquete INTO e FROM lf_ops.nucleo_evaluaciones WHERE regla=cd AND version=(p->>'version')::int ORDER BY id DESC LIMIT 1;
 IF ((SELECT count(*) FROM lf_ops.reglas)=586 AND e.id IS DISTINCT FROM (p->>'eval_id')::bigint) OR e.hash_paquete IS DISTINCT FROM p->>'hash_paquete_atestado' OR (SELECT count(*) FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=e.version)<>8 OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='CANDIDATA' AND hash=p->>'hash_version_atestado') THEN RAISE EXCEPTION 'S17_ATTESTATION_DRIFT %',cd; END IF;
 h:=lf_ops.nucleo_hash_paquete_v1(cd,e.version);
 IF h IS DISTINCT FROM e.hash_paquete THEN RAISE EXCEPTION 'S17_HASH_DRIFT %',cd; END IF;
 val:=jsonb_build_object('regla',cd,'hash_evaluado',h,'veredicto',p->>'veredicto','puntajes',p->'puntajes','juez',p->>'juez','modo','INDEPENDIENTE','revisor_es_productor',false,'llamadas_modelo',1,'evidencia_ref','sandbox/lf_contract_gate_test/nucleo_ci/nucleo_s17_juicios_4_v1.json#'||cd);
 BEGIN
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val||jsonb_build_object('hash_evaluado',repeat('0',64)));
 RAISE EXCEPTION 'S17_NEGATIVE_HASH_ACCEPTED %',cd;
 EXCEPTION WHEN others THEN IF SQLERRM NOT LIKE 'NUCLEO_JUICIO_HASH_DISTINTO:%' THEN RAISE; END IF; END;
 PERFORM lf_ops.nucleo_juicio_registrar_v1(val);
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 IF ans->>'decision'<>'AUTO' THEN RAISE EXCEPTION 'S17_NOT_AUTO % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_promover_v1(cd);
 IF ans->>'resultado'<>'PROMOVIDA_AUTO' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version AND estado='PUBLICADA') THEN RAISE EXCEPTION 'S17_PROMOTION_FAIL % %',cd,ans; END IF;
 pub:=pub+1;
 IF EXISTS(SELECT 1 FROM lf_ops.reglas WHERE id=lid) THEN
 IF EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada WHERE legacy_id=lid AND estado_cobertura='REEMPLAZADA') THEN RAISE EXCEPTION 'S17_COVERAGE_DRIFT %',lid; END IF;
 IF p->>'complementa' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM lf_ops.lf_nucleo_cobertura_legada c JOIN lf_ops.nucleo_regla_versiones v ON v.regla=c.nucleo_codigo AND v.version=c.version_nucleo WHERE c.legacy_id=lid AND c.nucleo_codigo=p->>'complementa' AND c.estado_cobertura='PARCIAL' AND v.estado='PUBLICADA') THEN RAISE EXCEPTION 'S17_COMPLEMENT_DRIFT %',lid; END IF;
 SELECT descripcion INTO old_desc FROM lf_ops.reglas WHERE id=lid;
 SELECT descripcion INTO new_desc FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=e.version;
 residual:=coalesce(p->>'residual',''); diff:=p->>'diferencias'||CASE WHEN residual<>'' THEN ' Residual: '||residual ELSE '' END;
 INSERT INTO lf_ops.lf_nucleo_cobertura_legada(legacy_id,nucleo_codigo,version_nucleo,estado_cobertura,diferencias,evidencia,hash_paquete,revisado_por)
 VALUES(lid,cd,e.version,CASE WHEN residual='' THEN 'REEMPLAZADA' ELSE 'PARCIAL' END,diff,jsonb_build_object('fuente','lf_ops.reglas/'||lid,'contraste','LEGADA: '||old_desc||' NUCLEO: '||new_desc||' DIFERENCIA: '||diff,'residual',residual,'juicio','Claude independiente S17 2026-11-24 13:35','limite_aceptacion','Cobertura funcional; binding runtime no certificado'),h,'GPT / Claude S17 independiente');
 links:=links+1;
 ELSIF (SELECT count(*) FROM lf_ops.reglas)=586 THEN RAISE EXCEPTION 'S17_SOURCE_MISSING %',lid; END IF;
 n:=n+1;
 END LOOP;
 IF n<>4 OR pub<>4 OR ((SELECT count(*) FROM lf_ops.reglas)=586 AND links<>4) OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY id) FROM lf_ops.reglas t) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(t) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones t) IS DISTINCT FROM b_dep THEN RAISE EXCEPTION 'S17_READBACK_FAIL n=% pub=% links=%',n,pub,links; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S17_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S17_PASS 4 JUICIOS 4 AUTO links=% DPIG03=0',links;
END $s17$;
COMMIT;
